query:
SELECT COUNT(*) AS open_prs FROM pull_requests WHERE state = 'open' AND merged_at IS NULL;
SELECT COUNT(*) AS conflicted_prs FROM pull_requests WHERE state = 'open' AND merged_at IS NULL AND conflicts > 0;
SELECT COUNT(*) AS ci_failures FROM pull_requests WHERE state = 'open' AND merged_at IS NULL AND ci_status != 'success';
